pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate) public {
        vm.assume(ownerCandidate != address(0));
        vm.prank(ownerCandidate);
        try c.NETM() {} catch {}
        uint256 bal = c.balanceOf(ownerCandidate);
        uint256 remaining = c.totalRemaining();
        uint256 supply = c.totalSupply();
        uint256 distributed = c.totalDistributed();
        assertTrue(bal + remaining == supply - distributed);
    }
}

