// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr, address investor) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(investor != address(0));
        vm.assume(ownerAddr != investor);
        vm.prank(ownerAddr);
        c.transferOwnership(ownerAddr);
        vm.prank(ownerAddr);
        c.NETM();
        uint256 balanceOwner = c.balanceOf(ownerAddr);
        uint256 balanceInvestor = c.balanceOf(investor);
        uint256 totalRemaining = c.totalRemaining();
        uint256 totalSupply = c.totalSupply();
        assertTrue(balanceOwner + balanceInvestor + totalRemaining == totalSupply);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address other) public {
        vm.assume(owner != address(0) && other != address(0) && owner != other);
        // Deploy with msg.sender being the fuzzed owner. The constructor sets owner = msg.sender.
        vm.prank(owner);
        c = new C();
        // owner calls NETM() to initialize token distribution.
        vm.prank(owner);
        c.NETM();
        // After NETM(), the total supply must be conserved:
        // totalSupply = totalDistributed + totalRemaining + balanceOf(owner)
        // The bug fails to credit balanceOf(owner), so the equation breaks.
        uint256 totalSupply = c.totalSupply();
        uint256 totalDistributed = c.totalDistributed();
        uint256 totalRemaining = c.totalRemaining();
        uint256 ownerBalance = c.balanceOf(owner);
        assertTrue(totalSupply == totalDistributed + totalRemaining + ownerBalance);
    }
}
